<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Graph, type Cell } from '@antv/x6'
import { createLayoutTask, type LayoutTask } from '../topology/layout-client'
import { kindLabel, lineagePresentation, type Lineage, type LineageNode, type LineageEdge } from '../api/topic-lineage'
const props=defineProps<{data:Lineage}>()
const emit=defineEmits<{selectNode:[node:LineageNode];selectEdge:[edge:LineageEdge]}>()
const host=ref<InstanceType<typeof globalThis.HTMLDivElement>>(),panel=ref<InstanceType<typeof globalThis.HTMLElement>>(),busy=ref(false),error=ref('')
let graph:Graph|undefined,task:LayoutTask|undefined,epoch=0,observer:InstanceType<typeof globalThis.ResizeObserver>|undefined,resizeFrame=0
function fit(){graph?.zoomToFit({padding:42,maxScale:1})}
function readableFit(){fit();if(graph&&graph.zoom()<0.72){graph.zoomTo(0.72);const root=graph.getCellById(props.data.root_id);if(root)graph.centerCell(root)}}
async function fullscreen(){try{if(globalThis.document.fullscreenElement)await globalThis.document.exitFullscreen();else await panel.value?.requestFullscreen();fit()}catch{error.value='当前浏览器无法进入全屏'}}
async function render(){const token=++epoch;task?.cancel();graph?.resetCells([]);busy.value=true;error.value='';task=createLayoutTask(lineagePresentation(props.data),238,88)
 try{const plan=await task.result;if(token!==epoch||!graph)return;const cells:Cell[]=[]
 for(const node of props.data.nodes){const p=plan.positions[node.id];if(!p)continue;const color=node.kind==='topic'?'#315fc1':node.kind==='mm2'?'#8060a8':node.kind==='unresolved'?'#ad7829':'#526578';const ports=props.data.edges.flatMap(e=>(['source','target'] as const).filter(end=>e[end]===node.id).map(end=>{const anchor=plan.ports[e.id]![end];return{id:`${e.id}:${end}`,group:'fixed',args:{x:anchor.side==='right'?238:0,y:anchor.offset}}}))
 cells.push(graph.createNode({id:node.id,shape:'rect',x:p.x,y:p.y,width:238,height:88,markup:[{tagName:'rect',selector:'body'},{tagName:'text',selector:'kind'},{tagName:'text',selector:'label'},{tagName:'text',selector:'cluster'}],ports:{groups:{fixed:{position:'absolute',attrs:{circle:{r:0}}}},items:ports},attrs:{body:{fill:node.id===props.data.root_id?'#eaf1ff':'#fff',stroke:color,strokeWidth:node.id===props.data.root_id?3:1.2,rx:6,ry:6},kind:{textAnchor:'start',text:kindLabel(node.kind)+(node.id===props.data.root_id?' · 当前根节点':''),refX:12,refY:17,fontSize:11,fill:color},label:{text:node.label,refX:12,refY:43,textAnchor:'start',fontSize:14,fontWeight:600,fill:'#25304a',textWrap:{width:214,height:24,ellipsis:true}},cluster:{text:node.cluster_name??(node.kind==='unresolved'?'关系待确认':''),refX:12,refY:69,fontSize:11,fill:'#6b778c',textAnchor:'start',textWrap:{width:214,height:18,ellipsis:true}}},data:node}))}
 for(const edge of props.data.edges){const route=plan.routes[edge.id];if(!route)continue;cells.push(graph.createEdge({id:edge.id,source:{cell:edge.source,port:`${edge.id}:source`},target:{cell:edge.target,port:`${edge.id}:target`},vertices:route.slice(1,-1),connector:{name:'rounded',args:{radius:5}},attrs:{line:{stroke:edge.evidence==='configured'?'#8060a8':edge.evidence==='unknown'?'#ad7829':'#60798d',strokeWidth:1.7,strokeDasharray:edge.evidence==='observed'?'0':'6 4',targetMarker:{name:'classic',size:7}}},labels:[],data:edge}))}
 graph.resetCells(cells);readableFit()
 }catch(e){if(token===epoch&&(e as Error).name!=='AbortError')error.value='自动布局失败，请重试'}finally{if(token===epoch)busy.value=false}}
onMounted(()=>{graph=new Graph({container:host.value!,autoResize:false,panning:true,mousewheel:{enabled:true,modifiers:['ctrl','meta'],minScale:0.15,maxScale:2},background:{color:'#f8faff'},grid:{visible:true,size:20},interacting:false});graph.on('node:click',({node})=>emit('selectNode',node.getData<LineageNode>()));graph.on('edge:click',({edge})=>emit('selectEdge',edge.getData<LineageEdge>()));void render();if(globalThis.ResizeObserver){observer=new globalThis.ResizeObserver(()=>{globalThis.cancelAnimationFrame(resizeFrame);resizeFrame=globalThis.requestAnimationFrame(()=>{if(graph&&panel.value&&host.value){graph.resize(panel.value.clientWidth-2,host.value.clientHeight);readableFit()}})});observer.observe(panel.value!)}})
watch(()=>props.data,()=>void render())
onBeforeUnmount(()=>{++epoch;task?.cancel();observer?.disconnect();globalThis.cancelAnimationFrame(resizeFrame);graph?.dispose()})
</script>
<template><section ref="panel" class="lineage-canvas"><div class="canvas-tools"><span>只读链路图</span><button aria-label="缩小链路图" @click="graph?.zoom(-0.15)">−</button><button aria-label="放大链路图" @click="graph?.zoom(0.15)">+</button><button @click="fit">适应画布</button><button @click="fullscreen">全屏</button></div><div ref="host" class="graph-host" role="img" aria-label="Topic 全链路画布" :aria-busy="busy" /><p v-if="busy" role="status" class="canvas-message">正在整理链路…</p><div v-if="error" role="alert" class="canvas-message">{{ error }} <button @click="render">重试布局</button></div></section></template>
<style scoped>.lineage-canvas{position:relative;min-width:0;border:1px solid #dce5ef;border-radius:8px;overflow:hidden;background:#f8faff}.lineage-canvas:fullscreen{height:100vh}.canvas-tools{display:flex;align-items:center;gap:8px;padding:10px 12px;background:#fff;border-bottom:1px solid #e2e8f0}.canvas-tools span{flex:1;color:#64748b;font-size:12px}.canvas-tools button{padding:5px 10px}.graph-host{height:550px}.lineage-canvas:fullscreen .graph-host{height:calc(100vh - 55px)}.canvas-message{position:absolute;left:20px;bottom:16px;background:#fff;padding:12px;border:1px solid #dce5ef;border-radius:4px}</style>
